9	// syntheticRecord fingerprints one record exactly as the store would,
10	// letting tests build chains that can never occur through the live API
11	// (e.g. a decision naming a version published later).
12	func syntheticRecord(org string, seq int, kind string, change *PolicyChange, decision *DecisionRecord, prev string) AuditRecord {
13		r := AuditRecord{
14			Org:             org,
15			Seq:             seq,
16			Kind:            kind,
17			Change:          change,
18			Decision:        decision,
19			PrevFingerprint: prev,
20		}
21		r.Fingerprint = fingerprintFor(&r)
22		return r
23	}
24	
25	// syntheticChain assumes a gapless, correctly fingerprinted chain.
26	func syntheticChain(org string, payloads []func(seq int) (string, *PolicyChange, *DecisionRecord)) ([]AuditRecord, Checkpoint) {
27		recs := make([]AuditRecord, 0, len(payloads))
28		prev := genesisFingerprint(org)
29		for i, build := range payloads {
30			seq := i + 1
31			kind, change, decision := build(seq)
32			r := syntheticRecord(org, seq, kind, change, decision, prev)
33			recs = append(recs, r)
34			prev = r.Fingerprint
35		}
36		return recs, Checkpoint{Org: org, EndSeq: len(recs), Fingerprint: prev}
37	}
