39	func TestOfflineReviewReplaysRecordedVersion(t *testing.T) {
40		s := NewStore()
41		v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
42		req := request("acme", "u1", "r1", "org/a", "read")
43		original := s.Decide("acme", req) // seq 2, version 1, allowed
44		origDeny := s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))
45	
46		// Later publishes and a rollback happen after the export material.
47		s.Publish("acme", 1, nil)
48		s.Rollback("acme", 2, 1)
49		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
50	
51		recs, cp, err := s.AuditExport("acme", 0)
52		if err != nil {
53			t.Fatal(err)
54		}
55	
56		got, err := RecheckDecisionOffline("acme", recs, cp, 2)
57		if err != nil {
58			t.Fatalf("offline review: %v", err)
59		}
60		if !got.Consistent {
61			t.Fatalf("review inconsistent: original=%+v recomputed=%+v", got.Original, got.Recomputed)
62		}
63		if !reflect.DeepEqual(got.Original, original) {
64			t.Fatalf("original = %+v, want %+v", got.Original, original)
65		}
66		if !reflect.DeepEqual(got.Recomputed, original) || got.Recomputed.Version != v1 {
67			t.Fatalf("recomputed = %+v, want %+v", got.Recomputed, original)
68		}
69		if got.Seq != 2 {
70			t.Fatalf("seq = %d, want 2", got.Seq)
71		}
72	
73		denied, err := RecheckDecisionOffline("acme", recs, cp, 3)
74		if err != nil {
75			t.Fatalf("offline review deny: %v", err)
76		}
77		if !denied.Consistent || !reflect.DeepEqual(denied.Original, origDeny) {
78			t.Fatalf("deny review = %+v, want consistent with %+v", denied, origDeny)
79		}
80		if denied.Recomputed.Allowed || denied.Recomputed.Reason != "no matching allow policy" {
81			t.Fatalf("recomputed deny = %+v", denied.Recomputed)
