116	func TestOfflineReviewVersionZeroCases(t *testing.T) {
117		s := NewStore()
118		// A legal request before any publish: not-yet-published denial, version 0.
119		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq1
120		// Envelope rejections are recorded too.
121		missing := request("acme", "u1", "r1", "org/a", "read")
122		missing.Action = ""
123		s.Decide("acme", missing) // seq2
124		mismatch := request("acme", "u1", "r1", "org/a", "read")
125		mismatch.SubjectOrg = "globex"
126		s.Decide("acme", mismatch) // seq3
127		badScope := request("acme", "u1", "r1", "org/../a", "read")
128		s.Decide("acme", badScope) // seq4
129		disabled := request("acme", "u1", "r1", "org/a", "read")
130		disabled.Subject.Disabled = true
131		s.Decide("acme", disabled) // seq5
132	
133		recs, cp, err := s.AuditExport("acme", 0)
134		if err != nil {
135			t.Fatal(err)
136		}
137		wantReasons := []string{
138			"organization has no published version",
139			"missing action",
140			"organization mismatch",
141			"invalid scope: scope \"org/../a\" contains invalid segment \"..\"",
142			"subject is disabled",
143		}
144		for seq, reason := range wantReasons {
145			got, err := RecheckDecisionOffline("acme", recs, cp, seq+1)
146			if err != nil {
147				t.Fatalf("seq %d: %v", seq+1, err)
148			}
149			if !got.Consistent {
150				t.Fatalf("seq %d inconsistent: %+v vs %+v", seq+1, got.Original, got.Recomputed)
151			}
152			if got.Original.Version != 0 || got.Recomputed.Version != 0 {
153				t.Fatalf("seq %d versions = %d/%d, want 0", seq+1, got.Original.Version, got.Recomputed.Version)
154			}
155			if got.Original.Allowed || got.Recomputed.Allowed || got.Recomputed.Reason != reason {
156				t.Fatalf("seq %d recomputed = %+v, want denial %q", seq+1, got.Recomputed, reason)
157			}
158		}
159	}
