161	func TestOfflineReviewValidationErrors(t *testing.T) {
162		s := NewStore()
163		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}) // seq1
164		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))                  // seq2
165		recs, cp, err := s.AuditExport("acme", 0)
