175				t.Fatalf("non-positive seq %d err = %v", seq, err)
176			}
177		}
178		if _, err := RecheckDecisionOffline("acme", recs, cp, 99); !errors.Is(err, ErrAuditNotFound) {
179			t.Fatalf("missing seq err = %v", err)
180		}
181		if _, err := RecheckDecisionOffline("acme", recs, cp, 1); !errors.Is(err, ErrAuditNotADecision) {
182			t.Fatalf("policy change target err = %v", err)
183		}
