185		// Empty export with the genesis checkpoint passes the chain check, but
186		// no decision can be reviewed.
187		empty, emptyCP, err := s.AuditExport("ghost", 0)
188		if err != nil {
189			t.Fatal(err)
190		}
191		if err := VerifyAudit("ghost", empty, emptyCP); err != nil {
