199	func TestOfflineReviewRejectsEveryTamperingIncludingAfterTarget(t *testing.T) {
200		s := NewStore()
201		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}) // seq1
202		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))                  // seq2 target
203		s.Publish("acme", 1, nil)                                                       // seq3
204		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))                  // seq4
205	
206		good, cp, err := s.AuditExport("acme", 0)
207		if err != nil {
208			t.Fatal(err)
209		}
210		mustFail := func(name string, mutate func([]AuditRecord) []AuditRecord, checkpoint Checkpoint) {
211			t.Helper()
212			recs := append([]AuditRecord(nil), good...)
213			recs = mutate(recs)
214			r, err := RecheckDecisionOffline("acme", recs, checkpoint, 2)
215			if err == nil {
216				t.Fatalf("%s: tampered material reviewed successfully: %+v", name, r)
217			}
218		}
219	
220		mustFail("rewrite target", func(r []AuditRecord) []AuditRecord {
221			r[1].Decision.Decision.Allowed = !r[1].Decision.Decision.Allowed
222			return r
223		}, cp)
224		mustFail("rewrite history policy", func(r []AuditRecord) []AuditRecord {
225			r[0].Change.Policies[0].Effect = EffectDeny
226			return r
227		}, cp)
228		mustFail("delete middle", func(r []AuditRecord) []AuditRecord {
229			return []AuditRecord{r[0], r[2], r[3]}
230		}, cp)
231		mustFail("delete tail after target", func(r []AuditRecord) []AuditRecord {
232			return r[:3]
233		}, cp)
234		mustFail("reorder", func(r []AuditRecord) []AuditRecord {
235			r[2], r[3] = r[3], r[2]
236			return r
237		}, cp)
238		mustFail("corruption after target", func(r []AuditRecord) []AuditRecord {
239			// Record 4 sits after the reviewed seq 2; its damage must count.
240			r[3].Decision.Request.Subject.ID = "hacker"
241			return r
242		}, cp)
243		mustFail("checkpoint fingerprint mismatch", func(r []AuditRecord) []AuditRecord { return r },
244			Checkpoint{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint + "x"})
245		mustFail("checkpoint end mismatch", func(r []AuditRecord) []AuditRecord { return r },
246			Checkpoint{Org: "acme", EndSeq: cp.EndSeq - 1, Fingerprint: cp.Fingerprint})
247	
248		// A record from another organization spliced after the target.
249		foreign := syntheticRecord("acme", 4, AuditDecision, nil, &DecisionRecord{
250			Request:  request("globex", "u2", "r1", "org/a", "read"),
251			Decision: Decision{Allowed: false, Version: 1},
252		}, good[2].Fingerprint)
253		spliced := append([]AuditRecord(nil), good[:3]...)
254		spliced = append(spliced, foreign)
255		mustFail("foreign org record", func([]AuditRecord) []AuditRecord { return spliced },
256			Checkpoint{Org: "acme", EndSeq: 4, Fingerprint: foreign.Fingerprint})
257	}
